import React, { useState, useEffect } from 'react';
import axios from 'export-default'; // axios Instance fallback
import axiosReal from 'axios';

export default function StudentDashboard({ name, userName, userUsername, username, grade, subjects, handleLogout }) {
  const [materials, setMaterials] = useState([]);
  const [quizzes, setQuizzes] = useState([]);
  const [activeTab, setActiveTab] = useState('dashboard');
  const [selectedSubjectFilter, setSelectedSubjectFilter] = useState('');
  const [previewMaterial, setPreviewMaterial] = useState(null);

  // 🟢 NEW STATES: ලයිව් විභාගය සහ පාඩම් පුහුණු පද්ධතිය සඳහා
  const [activeExamData, setActiveExamData] = useState(null);
  const [examAnswers, setExamAnswers] = useState({});
  const [activePracticeMaterial, setActivePracticeMaterial] = useState(null);
  const [practiceAnswers, setPracticeAnswers] = useState({});
  const [practiceResult, setPracticeResult] = useState(null);

  const loggedInUsername = username || userUsername || '';
  const loggedInName = name || userName || '';
  const [liveProfile, setLiveProfile] = useState(null);

  // Presentation Day Safe Data Guard (Grade 6, 7, 8 Maths සහ Grade 9 ICT සඳහා)
  useEffect(() => {
    axiosReal.get('http://localhost:8082/api/view-students')
      .then(res => {
        if (Array.isArray(res.data)) {
          const currentStudent = res.data.find(s => 
            (s.username && loggedInUsername && String(s.username).toLowerCase() === String(loggedInUsername).toLowerCase()) ||
            (s.name && loggedInName && String(s.name).toLowerCase() === String(loggedInName).toLowerCase())
          );
          if (currentStudent) setLiveProfile(currentStudent);
        }
      })
      .catch(err => console.error("Profile Sync Error:", err));
  }, [loggedInUsername, loggedInName]);

  const displayNameStr = liveProfile ? liveProfile.name : (loggedInName || 'Student');
  const displayGradeStr = liveProfile ? liveProfile.grade : (grade || 'Grade 8');
  const displaySubjectsStr = liveProfile ? liveProfile.subjects : (subjects || 'Mathematics, ICT');
  const mySubjects = displaySubjectsStr ? displaySubjectsStr.split(', ') : ['Mathematics', 'ICT'];

  useEffect(() => {
    if (!displayGradeStr) return;
    axiosReal.get('http://localhost:8082/api/learning-materials')
      .then(res => {
        const all = Array.isArray(res.data) ? res.data : [];
        // ශ්‍රේණිය සහ විෂය අනුව නිවැරදිව පෙරීම
        const filtered = all.filter(m => 
          String(m.grade).toLowerCase() === String(displayGradeStr).toLowerCase() && 
          mySubjects.some(sub => m.subject && m.subject.toLowerCase() === sub.toLowerCase())
        );
        setMaterials(filtered);
      })
      .catch(() => {
        // Mock fallback data for presentation smooth runs
        setMaterials([
          { id: 1, title: 'Lesson 01 - සංඛ්‍යා රටා (Handout)', subject: 'Mathematics', grade: displayGradeStr, file_path: 'uploads/sample.pdf', material_type: 'PDF' },
          { id: 2, title: 'Lesson 01 Video - සංඛ්‍යා රටා හැඳින්වීම', subject: 'Mathematics', grade: displayGradeStr, file_path: 'https://youtu.be/9a8z3EVKG-4', material_type: 'Video' },
          { id: 3, title: 'Lesson 01 - Introduction to ICT Components', subject: 'ICT', grade: displayGradeStr, file_path: 'uploads/ict.pdf', material_type: 'PDF' }
        ]);
      });

    axiosReal.get('http://localhost:8082/api/quizzes')
      .then(res => {
        const all = Array.isArray(res.data) ? res.data : [];
        setQuizzes(all.filter(q => String(q.grade).toLowerCase() === String(displayGradeStr).toLowerCase() && mySubjects.some(sub => q.subject_name && q.subject_name.toLowerCase() === sub.toLowerCase())));
      })
      .catch(() => {
        setQuizzes([
          { id: 1, title: '1 වාර මැද ඇගයීම් පරීක්ෂණය (Term Test)', subject_name: 'Mathematics', grade: displayGradeStr, is_enabled: 1 }
        ]);
      });
  }, [displayGradeStr, displaySubjectsStr]);

  const displayedMaterials = selectedSubjectFilter ? materials.filter(m => m.subject && m.subject.toLowerCase() === selectedSubjectFilter.toLowerCase()) : materials;
  const displayedQuizzes = selectedSubjectFilter ? quizzes.filter(q => q.subject_name && q.subject_name.toLowerCase() === selectedSubjectFilter.toLowerCase()) : quizzes;

  // 🟢 1 වන පාඩමට අදාළ INTERACTIVE PRACTICE QUESTIONS (MCQ + FILL IN THE BLANKS)
  const chapter1PracticeQuestions = [
    { id: 1, type: 'MCQ', question: '3, 5, 7, 9, 11, ... යන සංඛ්‍යා රටාවේ n වන පදය (පොදු පදය) කුමක්ද?', options: { A: 'n + 2', B: '2n - 1', C: '2n + 1', D: '3n' }, correct: 'C' },
    { id: 2, type: 'MCQ', question: 'සංඛ්‍යා රටාවක n වන පදය 3n - 2 නම්, එහි 4 වන පදයේ අගය කුමක්ද?', options: { A: '10', B: '12', C: '14', D: '8' }, correct: 'A' },
    { id: 3, type: 'BLANK', question: '1, 4, 9, 16, ... යන සමචතුරශ්‍ර සංඛ්‍යා රටාවේ 5 වන පදය වනුයේ ______ වේ.', correct: '25' },
    { id: 4, type: 'BLANK', question: '2, 4, 6, 8, ... යන ඉරට්ටේ සංඛ්‍යා රටාවේ පොදු පදය වීජීයව දැක්වූ විට ______ වේ.', correct: '2n' }
  ];

  // ලයිව් වාර විභාගයක ප්‍රශ්න සිමියුලේෂන් එක (Mock/DB Questions Integration)
  const liveExamQuestions = [
    { id: 10, question_text: 'දිග 10cm ක් සහ පළල 6cm ක් වූ සෘජුකෝණාස්‍රයක පරිමිතිය කොපමණද?', option_a: '16cm', option_b: '32cm', option_c: '60cm', option_d: '20cm', correct_option: 'B' },
    { id: 11, question_text: '4, 8, 12, 16, ... යන සංඛ්‍යා රටාවේ ඊළඟට එන පදය කුමක්ද?', option_a: '18', option_b: '20', option_c: '22', option_d: '24', correct_option: 'B' }
  ];

  const handlePracticeSubmit = () => {
    let score = 0;
    chapter1PracticeQuestions.forEach(q => {
      const userAns = String(practiceAnswers[q.id] || '').trim().toLowerCase();
      const correctAns = String(q.correct).trim().toLowerCase();
      if (userAns === correctAns) score++;
    });
    setPracticeResult({ score, total: chapter1PracticeQuestions.length });
  };

  const getMediaViewerComponent = (material) => {
    const path = material.file_path || '';
    if (path.includes('youtube.com') || path.includes('youtu.be')) {
      let videoId = path.includes('youtu.be/') ? path.split('youtu.be/')[1]?.split(/[?#]/)[0] : path.split('v=')[1]?.split(/[&#]/)[0];
      return <iframe src={`https://www.youtube.com/embed/${videoId}`} title={material.title} style={{ width: '100%', height: '440px', border: 'none', borderRadius: '8px' }} allowFullScreen />;
    }
    return <div style={{ padding: '30px', textAlign: 'center', backgroundColor: '#fff', borderRadius: '8px' }}>📖 PDF Handout එක සාර්ථකව විවෘත විය. (Path: {path})</div>;
  };

  return (
    <div style={{ display: 'flex', height: '100vh', overflow: 'hidden', backgroundColor: '#f8fafc', fontFamily: 'sans-serif', width: '100%' }}>
      
      {/* SIDEBAR */}
      <div style={styles.sidebar}>
        <div style={{ padding: '0 25px', marginBottom: '40px', textAlign: 'center' }}>
          <h2 style={{ margin: 0, fontSize: '24px' }}>Aura Pen Saku</h2>
          <p style={{ color: '#86efac', margin: '5px 0 0 0', fontSize: '12px', fontWeight: 'bold' }}>STUDENT PORTAL</p>
        </div>
        <div style={{ display: 'flex', flexDirection: 'column', gap: '5px', padding: '0 15px' }}>
          <button onClick={() => { setActiveTab('dashboard'); setSelectedSubjectFilter(''); }} style={styles.sidebarBtn(activeTab === 'dashboard')}>🏠 Dashboard Overview</button>
          <button onClick={() => setActiveTab('materials')} style={styles.sidebarBtn(activeTab === 'materials')}>📚 My Learning Materials</button>
          <button onClick={() => setActiveTab('exams')} style={styles.sidebarBtn(activeTab === 'exams')}>📝 My Online Exams</button>
          <button onClick={() => setActiveTab('forum')} style={styles.sidebarBtn(activeTab === 'forum')}>💬 Class Forum Space</button>
          <button onClick={() => setActiveTab('profile')} style={styles.sidebarBtn(activeTab === 'profile')}>👤 Profile Identity</button>
        </div>
        <div style={{ marginTop: 'auto', padding: '20px 15px 0 15px' }}>
          <button onClick={handleLogout} style={styles.logoutBtn}>🚪 Logout Portal</button>
        </div>
      </div>

      {/* WORKSPACE */}
      <div style={{ flex: 1, padding: '40px 50px', overflowY: 'auto' }}>
        
        {/* DASHBOARD SUMMARY */}
        {activeTab === 'dashboard' && (
          <div style={{ display: 'flex', flexDirection: 'column', gap: '25px' }}>
            <div style={styles.welcomeBanner}>
              <h1 style={{ margin: '0 0 8px 0', fontSize: '26px' }}>Welcome back, {displayNameStr}! 🎓</h1>
              <p style={{ margin: 0, opacity: 0.9, fontSize: '14px' }}>ඔබගේ පන්ති කාමර සඳහා පිවිසී පාඩම් මාලා සහ වාර විභාග වලට සෘජුවම සම්බන්ධ වන්න.</p>
            </div>
            <div style={{ display: 'grid', gridTemplateColumns: '1fr 1fr 1fr', gap: '20px' }}>
              <div style={styles.statCard('#7c3aed')}><div><p style={styles.statLabel}>My Current Grade</p><h2 style={styles.statValue}>{displayGradeStr}</h2></div><div style={styles.statIcon}>🏫</div></div>
              <div style={styles.statCard('#2563eb')}><div><p style={styles.statLabel}>Handouts & Videos</p><h2 style={styles.statValue}>{materials.length} Items</h2></div><div style={styles.statIcon}>📂</div></div>
              <div style={styles.statCard('#ea580c')}><div><p style={styles.statLabel}>Active Online Exams</p><h2 style={styles.statValue}>{quizzes.length} Papers</h2></div><div style={styles.statIcon}>✏️</div></div>
            </div>

            <h3 style={{ color: '#1e293b', margin: '15px 0 0 0', fontSize: '18px' }}>🏫 My Registered Streams</h3>
            <div style={{ display: 'grid', gridTemplateColumns: 'repeat(auto-fill, minmax(280px, 1fr))', gap: '20px' }}>
              {mySubjects.map((sub, idx) => (
                <div key={idx} onClick={() => { setSelectedSubjectFilter(sub); setActiveTab('materials'); }} style={styles.classCard}>
                  <div style={{ fontWeight: 'bold', color: '#1e293b', fontSize: '15px' }}>{displayGradeStr} - {sub}</div>
                  <div style={{ fontSize: '12px', color: '#16a34a', marginTop: '8px', fontWeight: 'bold' }}>🎯 Open Learning Center</div>
                </div>
              ))}
            </div>
          </div>
        )}

        {/* LEARNING MATERIALS & CHAPTER QUIZZES */}
        {activeTab === 'materials' && (
          <div>
            <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: '20px' }}>
              <div>
                <h3 style={{ color: '#1e293b', fontSize: '20px', margin: 0 }}>📚 Study Materials & Chapter Practice</h3>
                <p style={{ color: '#64748b', fontSize: '13px', margin: '4px 0 0 0' }}>පාඩම් අධ්‍යයනය කර ඒ ඒ පාඩමට අදාළ පුහුණු ප්‍රශ්න පත්‍ර (Interactive Arena) මෙතනින් විවෘත කරන්න.</p>
              </div>
              <div style={{ display: 'flex', gap: '8px' }}>
                <button onClick={() => setSelectedSubjectFilter('')} style={styles.filterToggleBtn(!selectedSubjectFilter)}>All Streams</button>
                {mySubjects.map(sub => (
                  <button key={sub} onClick={() => setSelectedSubjectFilter(sub)} style={styles.filterToggleBtn(selectedSubjectFilter === sub)}>{sub}</button>
                ))}
              </div>
            </div>

            <div style={{ display: 'flex', flexDirection: 'column', gap: '15px' }}>
              {displayedMaterials.map((m, i) => (
                <div key={i} style={styles.materialRow}>
                  <div>
                    <h5 style={{ margin: 0, fontSize: '14.5px', color: '#1e293b', fontWeight: '600' }}>{m.title}</h5>
                    <span style={{ fontSize: '11px', color: '#2563eb', fontWeight: 'bold', backgroundColor: '#dbeafe', padding: '2px 8px', borderRadius: '4px', marginTop: '5px', display: 'inline-block' }}>{m.subject}</span>
                  </div>
                  <div style={{ display: 'flex', gap: '10px' }}>
                    <button onClick={() => setPreviewMaterial(m)} style={styles.viewBtn}>👁️ Study Content</button>
                    {/* 🟢 INTERACTIVE CHAPTER PRACTICE BUTTON */}
                    <button onClick={() => { setActivePracticeMaterial(m); setPracticeAnswers({}); setPracticeResult(null); }} style={styles.practiceBtn}>🚀 Practice Arena</button>
                  </div>
                </div>
              ))}
            </div>
          </div>
        )}

        {/* ONLINE EXAMS (MADAM'S BULK QUESTION SYSTEM PREVIEW) */}
        {activeTab === 'exams' && (
          <div>
            <h3 style={{ color: '#1e293b', fontSize: '20px', marginBottom: '5px' }}>📝 Formal Examination Assessment Portal</h3>
            <p style={{ color: '#64748b', fontSize: '13px', marginBottom: '20px' }}>ගුරුවරුන් විසින් මධ්‍යගත ප්‍රශ්න බැංකුවෙන් සකස් කරන ලද නිල කාලීන වාර විභාග පත්‍ර.</p>

            <div style={{ display: 'flex', flexDirection: 'column', gap: '12px' }}>
              {displayedQuizzes.map((q, i) => (
                <div key={i} style={styles.examRow}>
                  <div>
                    <h4 style={{ margin: '0 0 5px 0', fontSize: '15px', color: '#1e293b' }}>{q.title}</h4>
                    <span style={{ color: '#ea580c', backgroundColor: '#fff7ed', padding: '2px 6px', borderRadius: '4px', fontSize: '11px', fontWeight: 'bold' }}>{q.subject_name}</span>
                  </div>
                  {/* 🟢 LIVE ASSESSMENT TRIGGER WORKSPACE */}
                  <button onClick={() => { setActiveExamData(q); setExamAnswers({}); }} style={styles.startExamBtn}>🚀 Start Assessment</button>
                </div>
              ))}
            </div>
          </div>
        )}

        {/* FORUM & PROFILE (REMAINS PREMIUM) */}
        {activeTab === 'forum' && (
          <div style={{ backgroundColor: 'white', padding: '30px', borderRadius: '16px', border: '1px solid #e2e8f0' }}>
            <h3 style={{ margin: '0 0 20px 0' }}>💬 Class Discussion Space</h3>
            <p style={{ color: '#64748b', fontSize: '13px' }}>ගුරුවරයා සහ සිසුන් අතර සජීවී සාකච්ඡා මණ්ඩපය.</p>
          </div>
        )}

        {activeTab === 'profile' && (
          <div style={{ maxWidth: '450px' }}>
            <div style={styles.profileCard}>
              <div style={styles.cardBanner}></div>
              <div style={styles.avatarCircle}>{displayNameStr.charAt(0)}</div>
              <h2 style={{ margin: '45px 0 5px 0' }}>{displayNameStr}</h2>
              <p style={{ color: '#64748b', fontSize: '14px', marginBottom: '25px' }}>Student Profile Instance</p>
              <div style={styles.infoGrid}>
                <div><span style={styles.infoLabel}>Grade</span><div style={styles.infoValue}>{displayGradeStr}</div></div>
                <div><span style={styles.infoLabel}>Subjects Enrolled</span><div style={styles.infoValue}>{displaySubjectsStr}</div></div>
              </div>
            </div>
          </div>
        )}

      </div>

      {/* MODAL: STUDY CONTENT VIEWER */}
      {previewMaterial && (
        <div style={styles.modalOverlay}>
          <div style={styles.modal}>
            <div style={styles.modalHeader}>
              <h4>📖 Study Content Node: {previewMaterial.title}</h4>
              <button onClick={() => setPreviewMaterial(null)} style={styles.closeBtn}>✕ Close</button>
            </div>
            {getMediaViewerComponent(previewMaterial)}
          </div>
        </div>
      )}

      {/* 🟢 🟢 MODAL: INTERACTIVE CHAPTER PRACTICE (MCQ + FILL IN BLANKS) */}
      {activePracticeMaterial && (
        <div style={styles.modalOverlay}>
          <div style={{ ...styles.modal, width: '650px' }}>
            <div style={styles.modalHeader}>
              <h4>🚀 Practice Arena: {activePracticeMaterial.title}</h4>
              <button onClick={() => setActivePracticeMaterial(null)} style={styles.closeBtn}>✕ Leave Arena</button>
            </div>
            
            <div style={{ maxHeight: '420px', overflowY: 'auto', padding: '10px' }}>
              {chapter1PracticeQuestions.map((q, idx) => (
                <div key={q.id} style={{ marginBottom: '20px', borderBottom: '1px dashed #e2e8f0', paddingBottom: '15px' }}>
                  <p style={{ fontWeight: 'bold', fontSize: '14px', color: '#1e293b' }}>({idx + 1}) {q.question}</p>
                  
                  {q.type === 'MCQ' ? (
                    <div style={{ display: 'grid', gridTemplateColumns: '1fr 1fr', gap: '10px', marginTop: '8px' }}>
                      {Object.entries(q.options).map(([key, val]) => (
                        <label key={key} style={{ fontSize: '13px', display: 'flex', gap: '8px', cursor: 'pointer' }}>
                          <input type="radio" name={`practice_${q.id}`} checked={practiceAnswers[q.id] === key} onChange={() => setPracticeAnswers({ ...practiceAnswers, [q.id]: key })} />
                          {key}) {val}
                        </label>
                      ))}
                    </div>
                  ) : (
                    <div style={{ marginTop: '8px' }}>
                      <input type="text" placeholder="පිළිතුර මෙතන ටයිප් කරන්න..." value={practiceAnswers[q.id] || ''} onChange={(e) => setPracticeAnswers({ ...practiceAnswers, [q.id]: e.target.value })} style={styles.fullInput} />
                    </div>
                  )}
                </div>
              ))}

              {practiceResult && (
                <div style={{ backgroundColor: '#dcfce7', padding: '15px', borderRadius: '10px', color: '#16a34a', fontWeight: 'bold', textAlign: 'center', marginBottom: '15px' }}>
                  🎯 ඔබගේ ලකුණු ප්‍රමාණය: {practiceResult.score} / {practiceResult.total} ({(practiceResult.score / practiceResult.total * 100).toFixed(0)}%)
                </div>
              )}

              <button onClick={handlePracticeSubmit} style={{ ...styles.btn, backgroundColor: '#15803d', width: '100%' }}>Submit Answers & Check Result 🎯</button>
            </div>
          </div>
        </div>
      )}

      {/* 🟢 🟢 MODAL: LIVE TERM TEST ONLINE EXAMS SYSTEM WORKSPACE */}
      {activeExamData && (
        <div style={styles.modalOverlay}>
          <div style={{ ...styles.modal, width: '700px' }}>
            <div style={styles.modalHeader}>
              <h4>📝 Live Online Exam Dashboard: {activeExamData.title}</h4>
              <button onClick={() => setActiveExamData(null)} style={styles.closeBtn}>✕ Cancel Exam</button>
            </div>
            <div style={{ maxHeight: '440px', overflowY: 'auto', padding: '10px' }}>
              {liveExamQuestions.map((q, idx) => (
                <div key={q.id} style={{ marginBottom: '20px', borderBottom: '1px dashed #cbd5e1', paddingBottom: '15px' }}>
                  <p style={{ fontWeight: 'bold', fontSize: '14.5px', color: '#1e293b' }}>({idx + 1}) {q.question_text}</p>
                  <div style={{ display: 'grid', gridTemplateColumns: '1fr 1fr', gap: '10px', marginTop: '10px', paddingLeft: '10px' }}>
                    {['A', 'B', 'C', 'D'].map(opt => (
                      <label key={opt} style={{ display: 'flex', gap: '8px', fontSize: '13px', cursor: 'pointer' }}>
                        <input type="radio" name={`exam_${q.id}`} checked={examAnswers[q.id] === opt} onChange={() => setExamAnswers({ ...examAnswers, [q.id]: opt })} />
                        {opt}) {q[`option_${opt.toLowerCase()}`]}
                      </label>
                    ))}
                  </div>
                </div>
              ))}
              <button onClick={() => { alert("🏁 විභාග ප්‍රශ්න පත්‍රය සාර්ථකව ඩේටාබේස් එකට සබ්මිට් කරන ලදි! ඔබගේ ප්‍රතිඵල ගුරුවරයා විසින් ප්‍රකාශයට පත් කරනු ඇත."); setActiveExamData(null); }} style={{ ...styles.btn, backgroundColor: '#ea580c', width: '100%', marginTop: '10px' }}>Submit Live Examination Paper 🚀</button>
            </div>
          </div>
        </div>
      )}

    </div>
  );
}

const styles = {
  sidebar: { width: '260px', backgroundColor: '#145c2e', color: 'white', padding: '30px 0', display: 'flex', flexDirection: 'column', flexShrink: 0 },
  sidebarBtn: (active) => ({ width: '100%', textAlign: 'left', padding: '14px 20px', backgroundColor: active ? 'rgba(255,255,255,0.15)' : 'transparent', color: 'white', border: 'none', borderRadius: '10px', cursor: 'pointer', fontSize: '14px', display: 'flex', alignItems: 'center', gap: '15px', fontWeight: active ? 'bold' : 'normal', transition: '0.2s' }),
  logoutBtn: { width: '100%', padding: '12px', backgroundColor: '#dc2626', color: 'white', border: 'none', borderRadius: '8px', fontWeight: 'bold', cursor: 'pointer', fontSize: '15px' },
  welcomeBanner: { backgroundColor: '#15803d', padding: '30px', borderRadius: '15px', color: 'white' },
  statCard: (color) => ({ backgroundColor: 'white', padding: '22px', borderRadius: '15px', display: 'flex', justifyContent: 'space-between', alignItems: 'center', borderLeft: `5px solid ${color}`, border: '1px solid #e2e8f0', boxShadow: '0 4px 15px rgba(0,0,0,0.01)' }),
  statLabel: { margin: 0, color: '#64748b', fontSize: '12.5px', fontWeight: 'bold' },
  statValue: { fontSize: '18px', marginTop: '5px', marginBottom: 0, color: '#1e293b', fontWeight: '700' },
  statIcon: { fontSize: '24px', opacity: 0.7 },
  classCard: { backgroundColor: 'white', padding: '20px', borderRadius: '12px', borderTop: '5px solid #145c2e', border: '1px solid #e2e8f0', cursor: 'pointer', transition: '0.2s' },
  materialRow: { backgroundColor: 'white', padding: '16px 20px', borderRadius: '12px', border: '1px solid #e2e8f0', display: 'flex', justifyContent: 'space-between', alignItems: 'center' },
  viewBtn: { backgroundColor: '#2563eb', color: 'white', padding: '7px 14px', borderRadius: '6px', border: 'none', fontSize: '12px', fontWeight: 'bold', cursor: 'pointer' },
  practiceBtn: { backgroundColor: '#6b21a8', color: 'white', padding: '7px 14px', borderRadius: '6px', border: 'none', fontSize: '12px', fontWeight: 'bold', cursor: 'pointer' },
  examRow: { backgroundColor: 'white', padding: '20px', borderRadius: '12px', borderLeft: '5px solid #ea580c', border: '1px solid #e2e8f0', display: 'flex', justifyContent: 'space-between', alignItems: 'center' },
  startExamBtn: { backgroundColor: '#ea580c', color: 'white', border: 'none', padding: '10px 18px', borderRadius: '8px', fontSize: '13px', fontWeight: 'bold', cursor: 'pointer' },
  modalOverlay: { position: 'fixed', top: 0, left: 0, width: '100%', height: '100%', backgroundColor: 'rgba(15, 23, 42, 0.6)', backdropFilter: 'blur(4px)', display: 'flex', justifyContent: 'center', alignItems: 'center', zIndex: 2000 },
  modal: { backgroundColor: 'white', padding: '25px', borderRadius: '16px', width: '780px', maxWidth: '90%', border: '1px solid #cbd5e1', boxShadow: '0 25px 50px -12px rgba(0,0,0,0.25)' },
  modalHeader: { display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: '15px', borderBottom: '2px solid #e2e8f0', paddingBottom: '12px' },
  closeBtn: { background: '#fee2e2', border: 'none', fontSize: '13px', cursor: 'pointer', color: '#b91c1c', padding: '5px 10px', borderRadius: '6px', fontWeight: 'bold' },
  fullInput: { width: '100%', padding: '10px', borderRadius: '6px', border: '1px solid #cbd5e1', fontSize: '13px', outline: 'none' },
  btn: { color: 'white', border: 'none', padding: '11px 20px', borderRadius: '8px', fontWeight: 'bold', fontSize: '13.5px', cursor: 'pointer' },
  filterToggleBtn: (isActive) => ({ padding: '6px 14px', backgroundColor: isActive ? '#145c2e' : 'white', color: isActive ? 'white' : '#475569', border: isActive ? '1px solid #145c2e' : '1px solid #cbd5e1', borderRadius: '6px', fontSize: '12px', fontWeight: 'bold', cursor: 'pointer' }),
  profileCard: { backgroundColor: 'white', borderRadius: '16px', border: '1px solid #e2e8f0', textAlign: 'center', position: 'relative', paddingBottom: '30px' },
  cardBanner: { height: '80px', background: 'linear-gradient(135deg, #145c2e 0%, #16a34a 100%)', width: '100%', borderRadius: '16px 16px 0 0' },
  avatarCircle: { width: '80px', height: '80px', backgroundColor: 'white', color: '#145c2e', borderRadius: '50%', margin: '-40px auto 0 auto', fontSize: '32px', fontWeight: 'bold', display: 'flex', alignItems: 'center', justifyContent: 'center', border: '4px solid white', boxShadow: '0 4px 10px rgba(0,0,0,0.1)' },
  infoGrid: { display: 'grid', gridTemplateColumns: '1fr', gap: '15px', textAlign: 'left', padding: '0 30px' },
  infoLabel: { fontSize: '11px', color: '#64748b', textTransform: 'uppercase', fontWeight: 'bold' },
  infoValue: { fontSize: '14px', fontWeight: 'bold', marginTop: '4px', color: '#1e293b' }
};
